precision highp float;
layout(std140) uniform HSLUBO {
  float placeholder;
  float hue;
  float saturation;
  float lightness;
};
vec3 RGBConvertToHSL(vec3 rgb) {
  float R = rgb.x, G = rgb.y, B = rgb.z;
  float maxValue = max(R, max(G, B));
  float minValue = min(R, min(G, B));
  float delta = maxValue - minValue;
  float hue, saturation, lightness;
  if (delta == 0.0){
    hue = 0.0;
  } else {
    float rMask = float(R == maxValue);
    float gMask = float(G == maxValue) * (1.0 - rMask);
    float bMask = float(B == maxValue) * (1.0 - rMask) * (1.0 - gMask);
    hue = (G - B) / delta * rMask + (2.0 + (B - R) / delta) * gMask + (4.0 + (R - G) / delta) * bMask;
  }
  hue = hue * 60.0;
  float h = mod(hue, 360.0);
  hue = h + (h < 0.0 ? 360.0 : 0.0);
  lightness = (maxValue + minValue) / 2.0;
  float den = 1.0 - abs(2.0 * lightness - 1.0);
  saturation = (abs(den) < 0.00001) ? 0.0 : (delta / den);
  hue = (abs(saturation) < 0.00001) ? 0.0 : hue;
  return vec3(hue, saturation, lightness);
}
vec3 HSLConvertToRGB(vec3 hsl) {
  float hue = hsl.x, saturation = hsl.y, lightness = hsl.z;
    float c = (1.0 - abs(2.0 * lightness - 1.0)) * saturation;
    float x = c * (1.0 - abs(mod(hue / 60.0, 2.0) - 1.0));
    float m = lightness - c / 2.0;
    float r, g, b;
    float h = mod(hue, 360.0) / 60.0;
    float segment = floor(h);
    if (segment == 0.0) {
        r = c;
        g = x;
        b = 0.0;
    } else if (segment == 1.0) {
        r = x;
        g = c;
        b = 0.0;
    } else if (segment == 2.0) {
        r = 0.0;
        g = c;
        b = x;
    } else if (segment == 3.0) {
        r = 0.0;
        g = x;
        b = c;
    } else if (segment == 4.0) {
        r = x;
        g = 0.0;
        b = c;
    } else {
        r = c;
        g = 0.0;
        b = x;
    }
    return vec3(r + m, g + m, b + m);
}
vec4 adjustHSL(vec4 color, float hue, float saturation, float lightness) {
  vec3 colorHSL = RGBConvertToHSL(color.rgb);
  colorHSL.r = mod(colorHSL.x + hue, 360.0);
  colorHSL.g = clamp(colorHSL.y + saturation, 0.0, 1.0);
  vec3 adjustedRGB = HSLConvertToRGB(colorHSL);
  float adjustBrightness = 1.0 + lightness;
  adjustedRGB.r = clamp(adjustedRGB.r * adjustBrightness, 0.0, 1.0);
  adjustedRGB.g = clamp(adjustedRGB.g * adjustBrightness, 0.0, 1.0);
  adjustedRGB.b = clamp(adjustedRGB.b * adjustBrightness, 0.0, 1.0);
  color = vec4(adjustedRGB, color.a);
  return color;
}
