    vec3 startRotation = a_rotation_uv.xyz;
  #endif
  #if CC_INSTANCE_PARTICLE
    vec3 startRotation = a_rotation_rnd.xyz;
  #endif
  #if CC_RENDER_MODE != 4
    #if CC_RENDER_MODE == 0
      vec3 rotEuler = startRotation.xyz;
    #elif CC_RENDER_MODE == 1
      vec3 rotEuler = vec3(0.);
