  #if COLOR_OVER_TIME_MODULE_ENABLE
    if (u_color_mode == 1) {
      color = a_color * texture(color_over_time_tex0, timeCoord0);
    } else {
      vec4 color_0 = texture(color_over_time_tex0, timeCoord0);
      vec4 color_1 = texture(color_over_time_tex0, timeCoord1);
