  uv = computeUV(frameIndex, vertIdx, frameTile_velLenScale.xy) * mainTiling_Offset.xy + mainTiling_Offset.zw;
  if (additionalParams.z != -1.0) {
    color.a *= additionalParams.z;
  }
  return pos;
}
