  float unit_x = velocity.x / magnitude;
  float unit_y = velocity.y / magnitude;
  float unit_z = velocity.z / magnitude;
  if (additionalParams.y == 0.0) {
    pos.xyz += velocity.xyz * normalizedTime * a_dir_life.w;
  }
  else if (magnitude != 0.0)  {
    float a0 = (additionalParams.y - additionalParams.x) * pseudoRandom(randSeed) + additionalParams.x;
    float newNormalizedTime = normalizedTime * a_dir_life.w;
