  #endif
  #if !COLOR_OVER_TIME_MODULE_ENABLE
    color = a_color;
  #endif
  #if CC_RENDER_MODE != 4
    vec2 cornerOffset = vec2((vertIdx - 0.5));
    #if CC_RENDER_MODE == 1
      rot = vec4(0.0, 0.0, 0.0, 1.0);
    #endif
    computeVertPos(pos, cornerOffset, rot, compScale
