        , cc_matViewInv
      #endif
      #if CC_RENDER_MODE == 1
        , cc_cameraPos.xyz
        , velocity
        , frameTile_velLenScale.z
        , frameTile_velLenScale.w
        #if !CC_INSTANCE_PARTICLE
          , a_size_uv.w
        #endif
        #if CC_INSTANCE_PARTICLE
