vec4 CCFragOutput (vec4 color) {
  return color;
}
precision highp float;
   uniform float blackThreshold;
vec4 blackToTransparent(vec4 original_color){
  bool isTransparent = length(original_color.rgb) < (blackThreshold / 100.0);
  return mix(original_color, vec4(0, 0, 0, 0), float(isTransparent));
}
varying vec2 uv;
varying vec4 color;
uniform sampler2D mainTexture;
vec4 addSmooth () {
  if (blackThreshold > 0.0) {
    vec4 originColor = texture2D(mainTexture, uv);
    originColor = blackToTransparent(originColor);
    if (originColor.a == 0.0) {
      return CCFragOutput(vec4(0, 0, 0, 0));
    }
  }
  vec4 col = color * texture2D(mainTexture, uv);
  col.rgb *= col.a;
  return CCFragOutput(col);
}
void main() { gl_FragColor = addSmooth(); }

